class WavyValley:
    def __init__(self, dim=5):
        self.dim = dim
        self.amplitude_decay = 0.8  # Controls global-local contrast

    def f(self, x):
        if len(x) != self.dim:
            raise ValueError(f"Input dimension must be {self.dim}")
        total = 0.0
        for i in range(self.dim):
            # Each dimension contributes a decaying sinusoidal component
