import numpy as np

class WavyValley:
    def __init__(self, dim=5):
        self.dim = dim
        self.amplitude = 1.0  # Controls GlobalLocal contrast

    def f(self, x):
        # Each dimension contributes a wavy pattern with global min at 0
        # and local minima at ±2, ±4 (within [-5,5] bounds)
        wavy = np.abs(np.sin(x * np.pi)) * self.amplitude
        # Add quadratic term to ensure global minimum at 0
        quadratic = 0.5 * (x ** 2)
        return np.sum(wavy + quadratic)

