class ExponentiallyGatedHarmonicWell:
    def __init__(self, dim=5):
        self.dim = dim
        self.decay_rate = 0.7  # Controls exponential decay of oscillation amplitude
        self.frequency = 5.0   # Number of oscillations in the search space
        self.baseline = 1.0    # Minimum amplitude of oscillatory component

    def f(self, x):
        if len(x) != self.dim:
            raise ValueError(f"Input dimension must be {self.dim}")

        def dimension_function(xi):
            # Strong quadratic global well at origin (f(0) = baseline at xi=0)
            # This creates the deep global minimum
            global_well = xi**2

            # Oscillatory component with exponential gating
            # Amplitude decreases with distance from origin via exponential decay
            oscillation = (self.baseline + np.sin(self.frequency * np.pi * xi)**2) * np.exp(-self.decay_rate * np.abs(xi))

            # Combined ensures non-negative with clear global minimum at 0
            return global_well + oscillation

        return sum(dimension_function(x[i]) for i in range(self.dim))
